using only the Python standard library; report.pdf is parsed (classic xref),
its objects renumbered, and a new root Pages/Catalog is written so the cover
page precedes the original report pages. Only report.pdf is modified
(atomically via os.replace); temporary files are removed at the end.
"""

import os
import re
import sys
from datetime import datetime

TITLE = "Annual Financial Report"
REPORT = "report.pdf"

HERE = os.path.dirname(os.path.abspath(__file__))
REPORT_PATH = os.path.join(HERE, REPORT)
COVER_PATH = os.path.join(HERE, "cover_tmp.pdf")
MERGED_PATH = os.path.join(HERE, "report_merged_tmp.pdf")

PAGE_W, PAGE_H = 612.0, 792.0
WS = b" \t\r\n\f\0"
DELIMS = b"()<>[]{}/%"

# Standard Helvetica-Bold widths (1/1000 em) for ASCII 32..126.
HB_WIDTHS = {
