    117: 611, 118: 556, 119: 778, 120: 556, 121: 556, 122: 500, 123: 389,
    124: 280, 125: 389, 126: 584,
}
# Standard Helvetica widths (1/1000 em) for ASCII 32..126.
H_WIDTHS = {
    32: 278, 33: 278, 34: 355, 35: 556, 36: 556, 37: 889, 38: 667, 39: 191,
    40: 333, 41: 333, 42: 389, 43: 584, 44: 278, 45: 333, 46: 278, 47: 278,
    48: 556, 49: 556, 50: 556, 51: 556, 52: 556, 53: 556, 54: 556, 55: 556,
    56: 556, 57: 556, 58: 278, 59: 278, 60: 584, 61: 584, 62: 584, 63: 556,
    64: 1015, 65: 667, 66: 667, 67: 722, 68: 722, 69: 667, 70: 611, 71: 778,
    72: 722, 73: 278, 74: 500, 75: 667, 76: 556, 77: 833, 78: 722, 79: 778,
    80: 667, 81: 778, 82: 722, 83: 667, 84: 611, 85: 722, 86: 667, 87: 944,
    88: 667, 89: 667, 90: 611, 91: 278, 92: 278, 93: 278, 94: 469, 95: 556,
    96: 333, 97: 556, 98: 556, 99: 500, 100: 556, 101: 556, 102: 278,
    103: 556, 104: 556, 105: 222, 106: 222, 107: 500, 108: 222, 109: 833,
    110: 556, 111: 556, 112: 556, 113: 556, 114: 333, 115: 500, 116: 278,
    117: 556, 118: 500, 119: 722, 120: 500, 121: 500, 122: 500, 123: 334,
    124: 260, 125: 334, 126: 584,
}


# ---------------------------------------------------------------- utilities

def text_width(text, widths, size):
    return sum(widths.get(ord(c), 500) for c in text) / 1000.0 * size


def esc_pdf(s):
    out = []
    for ch in s:
        o = ord(ch)
        if ch in "()\\":
            out.append("\\" + ch)
        elif 32 <= o <= 126:
            out.append(ch)
        else:
            out.append("\\%03o" % o)
    return "".join(out)


def skip_ws(data, i):
    n = len(data)
    while i < n:
        c = data[i]
        if c in WS:
            i += 1
        elif c == 0x25:  # '%' comment
            j = data.find(b"\n", i)
            i = n if j < 0 else j + 1
        else:
            break
    return i


def next_token(data, i):
    i = skip_ws(data, i)
    if i >= len(data):
        return None, i
    c = data[i]
    if c == 0x28:  # literal string (...)
        depth = 1
        j = i + 1
        while j < len(data) and depth:
            ch = data[j]
            if ch == 0x5C:  # backslash escape
                j += 2
                continue
            if ch == 0x28:
                depth += 1
            elif ch == 0x29:
                depth -= 1
            j += 1
        return data[i:j], j
    if c == 0x3C:  # < or <<
        if i + 1 < len(data) and data[i + 1] == 0x3C:
            return b"<<", i + 2
        j = data.find(b">", i + 1)
        if j < 0:
            j = len(data)
        return data[i:j + 1], j + 1
    if c == 0x3E:  # > or >>
        if i + 1 < len(data) and data[i + 1] == 0x3E:
            return b">>", i + 2
        return b">", i + 1
    if c in b"[]{}":
        return data[i:i + 1], i + 1
    if c == 0x2F:  # name
        j = i + 1
        while j < len(data) and data[j] not in DELIMS and data[j] not in WS:
            j += 1
        return data[i:j], j
    j = i
    while j < len(data) and data[j] not in DELIMS and data[j] not in WS:
        j += 1
    return data[i:j], j


def read_int(data, i):
    i = skip_ws(data, i)
    j = i
    while j < len(data) and data[j] in b"0123456789":
        j += 1
    if j == i:
        raise ValueError("expected integer")
    return int(data[i:j]), j


def find_ref(tokens, key):
    """Return object number for 'key N G R' in a token list, else None."""
    for i, t in enumerate(tokens):
        if (t == key and i + 3 < len(tokens) and tokens[i + 1].isdigit()
                and tokens[i + 2].isdigit() and tokens[i + 3] == b"R"):
            return int(tokens[i + 1])
    return None


def first_kid_ref(tokens):
    """Return the first object number in a '/Kids [ ... ]' array, else None."""
    for i, t in enumerate(tokens):
        if t == b"/Kids" and i + 1 < len(tokens) and tokens[i + 1] == b"[":
            j = i + 2
            if j < len(tokens) and tokens[j].isdigit():
                return int(tokens[j])
    return None


# ------------------------------------------------------------------- parsing

def read_object(data, offset):
    i = skip_ws(data, offset)
    num, i = read_int(data, i)
    gen, i = read_int(data, i)
    i = skip_ws(data, i)
    if data[i:i + 3] != b"obj":
        raise ValueError("bad object header")
    i += 3
    tokens = []
    stream_data = None
    j = i
    while True:
        j = skip_ws(data, j)
        if j >= len(data):
            raise ValueError("unterminated object")
        if data.startswith(b"endobj", j):
            break
        if data.startswith(b"stream", j):
            j += 6
            if data[j:j + 2] == b"\r\n":
                j += 2
            elif j < len(data) and data[j] in b"\r\n":
                j += 1
            # Prefer literal /Length to locate the stream end.
            length = None
            for k, t in enumerate(tokens):
                if t == b"/Length" and k + 1 < len(tokens) and tokens[k + 1].isdigit():
                    length = int(tokens[k + 1])
                    break
            if length is not None and data[j + length:j + length + 9] == b"endstream":
                stream_data = data[j:j + length]
                j += length + 9
                continue
            end = data.find(b"endstream", j)
            if end < 0:
                raise ValueError("unterminated stream")
            stream_data = data[j:end]
            j = end + 9
            continue
        tok, j = next_token(data, j)
        if tok is None:
            raise ValueError("tokenizer failed")
        tokens.append(tok)
    return num, gen, tokens, stream_data


def parse_pdf(path):
    data = open(path, "rb").read()
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        raise ValueError("startxref not found")
    xref_off = int(m.group(1))
    if data[xref_off:xref_off + 4] != b"xref":
        raise ValueError("classic xref table not found")
    pos = xref_off + 4
    entries = {}
    trailer_bytes = b""
    while True:
        pos = skip_ws(data, pos)
        if data.startswith(b"trailer", pos):
            tpos = pos + 7
            sx = data.find(b"startxref", tpos)
            if sx < 0:
                raise ValueError("trailer unterminated")
            trailer_bytes = data[tpos:sx].strip()
            break
        line_end = data.find(b"\n", pos)
        if line_end < 0:
            line_end = len(data)
        line = data[pos:line_end].strip()
        pos = line_end + 1
        parts = line.split()
        if len(parts) == 2 and parts[0].isdigit() and parts[1].isdigit():
            start, count = int(parts[0]), int(parts[1])
            for k in range(count):
                epos = skip_ws(data, pos)
                eol = data.find(b"\n", epos)
                if eol < 0:
                    eol = len(data)
                eparts = data[epos:eol].strip().split()
                pos = eol + 1
                if len(eparts) >= 3 and eparts[2] == b"n":
                    entries[start + k] = (int(eparts[0]), int(eparts[1]))
    if re.search(rb"/Encrypt\b", trailer_bytes):
        raise ValueError("encrypted PDF not supported")
    objects = {}
    for num, (off, gen) in entries.items():
        n, g, tokens, stream = read_object(data, off)
        if n != num:
            raise ValueError("object number mismatch")
        objects[num] = (tokens, stream)
    return data, objects, trailer_bytes


def count_pages(num, objects, seen=None):
    if seen is None:
        seen = set()
    if num in seen:
        return 0
    seen.add(num)
    tokens = objects[num][0]
    c = find_ref(tokens, b"/Count")
    if c is not None:
        return c
    if b"/Kids" not in tokens:
        return 1
    total = 0
    for i, t in enumerate(tokens):
        if t == b"/Kids" and i + 1 < len(tokens) and tokens[i + 1] == b"[":
            j = i + 2
            while j < len(tokens) and tokens[j] != b"]":
                if (tokens[j].isdigit() and j + 2 < len(tokens)
                        and tokens[j + 1].isdigit() and tokens[j + 2] == b"R"):
                    total += count_pages(int(tokens[j]), objects, seen)
                    j += 3
                else:
                    j += 1
            break
    return total


# ------------------------------------------------------------------ building

def rewrite_refs(tokens, offset):
    out = []
    i = 0
    n = len(tokens)
    while i < n:
        t = tokens[i]
        if (t.isdigit() and i + 2 < n and tokens[i + 1].isdigit()
                and tokens[i + 2] == b"R"):
            num = int(t)
            if num == 0:
                out.extend([b"0", tokens[i + 1], b"R"])
            else:
                out.extend([str(num + offset).encode(), tokens[i + 1], b"R"])
            i += 3
            continue
        out.append(t)
        i += 1
    return out


def object_content(num, gen, tokens, stream):
    parts = [b"%d %d obj" % (num, gen), b" ".join(tokens)]
    if stream is not None:
        parts.append(b"stream\n" + stream + b"\nendstream")
    parts.append(b"endobj")
    return b"\n".join(parts)


def write_pdf(path, objects, root, info_ref=None):
    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = {}
    nums = sorted(objects)
    for n in nums:
        offsets[n] = len(out)
        out += b"%d 0 obj\n" % n
        out += objects[n]
        out += b"\nendobj\n"
    xref_pos = len(out)
    size = max(nums) + 1
    out += b"xref\n0 %d\n" % size
    out += b"0000000000 65535 f \n"
    for n in range(1, size):
        if n in offsets:
            out += b"%010d 00000 n \n" % offsets[n]
        else:
            out += b"0000000000 65535 f \n"
    trailer = b"<< /Size %d /Root %d 0 R" % (size, root)
    if info_ref is not None:
        trailer += b" /Info %d 0 R" % info_ref
    trailer += b" >>"
    out += b"trailer\n" + trailer + b"\nstartxref\n" + str(xref_pos).encode() + b"\n%%EOF\n"
    with open(path, "wb") as f:
        f.write(out)


def build_cover(path, title, date_str):
    tsize, dsize = 28, 16
    tw = text_width(title, HB_WIDTHS, tsize)
    dw = text_width(date_str, H_WIDTHS, dsize)
    x1 = (PAGE_W - tw) / 2.0
    x2 = (PAGE_W - dw) / 2.0
    y_title, y_rule, y_date = 470.0, 448.0, 430.0
    ops = [
        "BT", "/F1 %d Tf" % tsize, "0 0 0 rg",
        "%.2f %.2f Td" % (x1, y_title), "(%s) Tj" % esc_pdf(title), "ET",
        "BT", "/F2 %d Tf" % dsize, "0 0 0 rg",
        "%.2f %.2f Td" % (x2, y_date), "(%s) Tj" % esc_pdf(date_str), "ET",
        "0.6 w", "0.45 0.45 0.45 RG",
        "%.2f %.2f m %.2f %.2f l S" % (150.0, y_rule, 462.0, y_rule),
    ]
    stream = ("\n".join(ops) + "\n").encode("latin-1")
    objects = {
        1: b"<< /Type /Catalog /Pages 2 0 R >>",
        2: b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        3: (b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
            b"/Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> "
            b"/Contents 6 0 R >>"),
        4: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold "
           b"/Encoding /WinAnsiEncoding >>",
        5: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica "
           b"/Encoding /WinAnsiEncoding >>",
        6: b"<< /Length %d >>\nstream\n" % len(stream) + stream + b"endstream",
    }
    write_pdf(path, objects, root=1)


# ---------------------------------------------------------------- merging

def merge_with_library(cover_path, report_path, out_path):
    for mod in ("pypdf", "PyPDF2"):
        try:
            mod = __import__(mod, fromlist=["PdfReader", "PdfWriter"])
            reader = mod.PdfReader(report_path)
            writer = mod.PdfWriter()
            writer.add_page(mod.PdfReader(cover_path).pages[0])
            for page in reader.pages:
                writer.add_page(page)
            with open(out_path, "wb") as f:
                writer.write(f)
            return True
        except Exception:
            continue
    return False


def manual_merge(cover_path, report_path, out_path):
    _, cover_objects, cover_trailer = parse_pdf(cover_path)
    _, report_objects, report_trailer = parse_pdf(report_path)
    for tokens, _stream in report_objects.values():
        if b"/ObjStm" in tokens or b"/XRef" in tokens:
            raise ValueError("object/xref streams not supported")

    mroot = re.search(rb"/Root\s+(\d+)", cover_trailer)
    if not mroot:
        raise ValueError("cover /Root missing")
    cover_cat_tokens = cover_objects[int(mroot.group(1))][0]
    cover_pages_num = find_ref(cover_cat_tokens, b"/Pages")
    cover_page_num = first_kid_ref(cover_objects[cover_pages_num][0])
    if cover_pages_num is None or cover_page_num is None:
        raise ValueError("cover page tree incomplete")

    mroot = re.search(rb"/Root\s+(\d+)", report_trailer)
    if not mroot:
        raise ValueError("report /Root missing")
    report_root = int(mroot.group(1))
    report_cat_tokens = report_objects[report_root][0]
    report_pages_num = find_ref(report_cat_tokens, b"/Pages")
    if report_pages_num is None:
        raise ValueError("report /Pages missing")
    report_count = count_pages(report_pages_num, report_objects)

    offset = max(cover_objects)  # cover objects occupy 1..offset
    max_report = max(report_objects)
    merged = {}
    for n, (tokens, stream) in cover_objects.items():
        merged[n] = object_content(n, 0, rewrite_refs(tokens, 0), stream)
    for n, (tokens, stream) in report_objects.items():
        merged[n + offset] = object_content(n + offset, 0,
                                            rewrite_refs(tokens, offset), stream)

    new_pages = offset + max_report + 1
    new_catalog = offset + max_report + 2
    merged[new_pages] = (b"<< /Type /Pages /Kids [%d 0 R %d 0 R] /Count %d >>"
                         % (cover_pages_num, report_pages_num + offset,
                            report_count + 1))
    cat_tokens = rewrite_refs(report_cat_tokens, offset)
    replaced = False
    for i, t in enumerate(cat_tokens):
        if (t == b"/Pages" and i + 3 < len(cat_tokens)
                and cat_tokens[i + 1].isdigit() and cat_tokens[i + 2].isdigit()
                and cat_tokens[i + 3] == b"R"):
            cat_tokens[i + 1] = str(new_pages).encode()
            cat_tokens[i + 2] = b"0"
            replaced = True
            break
    if not replaced:
        raise ValueError("catalog /Pages ref not found")
    merged[new_catalog] = b" ".join(cat_tokens)

    info_ref = None
    minfo = re.search(rb"/Info\s+(\d+)\s+\d+\s+R", report_trailer)
    if minfo:
        info_ref = int(minfo.group(1)) + offset

    write_pdf(out_path, merged, root=new_catalog, info_ref=info_ref)
    return report_count + 1, cover_page_num


# -------------------------------------------------------------- validation

def validate(path, expected_count, title, date_str):
    _, objects, trailer = parse_pdf(path)
    mroot = re.search(rb"/Root\s+(\d+)", trailer)
    if not mroot:
        raise AssertionError("merged /Root missing")
    cat_tokens = objects[int(mroot.group(1))][0]
    pages_num = find_ref(cat_tokens, b"/Pages")
    if pages_num is None:
        raise AssertionError("merged /Pages missing")
    count = count_pages(pages_num, objects)
    if count != expected_count:
        raise AssertionError("expected %d pages, got %d" % (expected_count, count))
    first = first_kid_ref(objects[pages_num][0])
    if first is None:
        raise AssertionError("merged /Kids missing")
    contents_ref = find_ref(objects[first][0], b"/Contents")
    if contents_ref is None:
        raise AssertionError("cover /Contents missing")
    stream = objects[contents_ref][1]
    if stream is None:
        raise AssertionError("cover content stream missing")
    if title.encode("latin-1") not in stream:
        raise AssertionError("cover title text not found on page 1")
    if date_str.encode("latin-1") not in stream:
        raise AssertionError("cover date text not found on page 1")
    return count


def main():
    if not os.path.exists(REPORT_PATH):
        sys.exit("error: %s not found" % REPORT_PATH)
    date_str = datetime.now().strftime("%B %d, %Y")
    try:
        build_cover(COVER_PATH, TITLE, date_str)
        try:
            expected, cover_page = manual_merge(COVER_PATH, REPORT_PATH, MERGED_PATH)
        except Exception as exc:
            if merge_with_library(COVER_PATH, REPORT_PATH, MERGED_PATH):
                expected = None
                cover_page = None
            else:
                sys.exit("error: could not merge cover into report.pdf: %s" % exc)
        os.replace(MERGED_PATH, REPORT_PATH)
        if expected is None:
            # Library path: basic check with the same library.
            for mod in ("pypdf", "PyPDF2"):
                try:
                    reader = __import__(mod, fromlist=["PdfReader"]).PdfReader(REPORT_PATH)
                    text = (reader.pages[0].extract_text() or "")
                    if TITLE in text and date_str in text and len(reader.pages) >= 2:
                        print("OK: cover page added to report.pdf (%d pages); "
                              "page 1 contains '%s' and '%s'." % (len(reader.pages), TITLE, date_str))
                        return
                except Exception:
                    continue
            sys.exit("error: library merge validation failed")
        count = validate(REPORT_PATH, expected, TITLE, date_str)
        print("OK: cover page added to report.pdf (%d pages); page 1 contains "
              "'%s' and '%s'." % (count, TITLE, date_str))
    finally:
        for p in (COVER_PATH, MERGED_PATH):
            if os.path.exists(p):
                os.remove(p)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Validate that report.pdf now begins with a cover page containing the exact
title 'Annual Financial Report' and the current date, followed by the original
report pages. Validation only: does not modify report.pdf."""

import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from add_cover_stdlib import count_pages, find_ref, first_kid_ref, parse_pdf  # noqa: E402

TITLE = "Annual Financial Report"
REPORT_PATH = os.path.join(HERE, "report.pdf")


def leaf_page_num(num, objects):
    """Descend through nested /Kids nodes to the first actual page object."""
    tokens = objects[num][0]
    if b"/Contents" in tokens or b"/Kids" not in tokens:
        return num
    kid = first_kid_ref(tokens)
    if kid is None:
        return num
    return leaf_page_num(kid, objects)


def main():
    if not os.path.exists(REPORT_PATH):
        sys.exit("error: %s not found" % REPORT_PATH)
    _data, objects, trailer = parse_pdf(REPORT_PATH)
    mroot = re.search(rb"/Root\s+(\d+)", trailer)
    if not mroot:
        sys.exit("error: /Root missing in report.pdf")
    root = int(mroot.group(1))
    pages_num = find_ref(objects[root][0], b"/Pages")
    if pages_num is None:
        sys.exit("error: /Pages missing in report.pdf")
    total = count_pages(pages_num, objects)
    if total < 2:
        sys.exit("error: report.pdf should contain a cover page plus original pages")

    first = first_kid_ref(objects[pages_num][0])
    page1 = leaf_page_num(first, objects)
    contents_ref = find_ref(objects[page1][0], b"/Contents")
    if contents_ref is None:
        sys.exit("error: cover page has no content stream")
    stream = objects[contents_ref][1] or b""

    if TITLE.encode("latin-1") not in stream:
        sys.exit("error: title '%s' not found on page 1" % TITLE)
    mdate = re.search(rb"\(([A-Z][a-z]+ \d{1,2}, \d{4})\)", stream)
    if not mdate:
        sys.exit("error: no date found on page 1")
    date_text = mdate.group(1).decode("latin-1")

    # Exactly one page should carry the cover title.
    title_count = 0
    for _num, (tokens, s) in objects.items():
        if s and TITLE.encode("latin-1") in s:
            title_count += 1
    if title_count != 1:
        sys.exit("error: expected exactly one cover page, found %d" % title_count)

    # The original report content must still be present after page 1.
    page2_ok = False
    for num, (tokens, s) in objects.items():
        if num == page1:
            continue
        if s and len(s) > 0 and b"/Type" not in tokens:
            page2_ok = True
            break
    if not page2_ok:
        sys.exit("error: no additional page content found beyond the cover")

    print("VALIDATION OK: report.pdf has %d pages; page 1 contains '%s' and "
          "date '%s'; original pages follow the cover." % (total, TITLE, date_text))


if __name__ == "__main__":
    main()

