import zlib

HERE = os.path.dirname(os.path.abspath(__file__))
REPORT = os.path.join(HERE, "report.pdf")

with open(REPORT, "rb") as f:
    data = f.read()

print(f"size: {len(data)} bytes")
m = re.search(rb"%PDF-(\d+\.\d+)", data)
print("version:", m.group(1).decode() if m else "?")

# ---------- tokenizer for PDF objects ----------
class Tok:
    def __init__(self, data):
        self.data = data
        self.pos = 0

    def skip_ws(self):
        d, n = self.data, len(self.data)
        while self.pos < n:
            c = d[self.pos]
            if c in b" \t\r\n\f\0":
                self.pos += 1
            elif c == 0x25:  # '%' comment
                while self.pos < n and d[self.pos] not in b"\r\n":
                    self.pos += 1
            else:
                break

    def next(self):
        self.skip_ws()
        d, n = self.data, len(self.data)
        if self.pos >= n:
            return None
        c = d[self.pos]
        if c == 0x3C:  # '<'
            if self.pos + 1 < n and d[self.pos + 1] == 0x3C:  # <<
                self.pos += 2
                return "<<"
            self.pos += 1
            end = d.find(b">", self.pos)
            s = d[self.pos:end]
            self.pos = end + 1
            return ("hexstr", s)
        if c == 0x3E:  # '>'
            self.pos += 2
            return ">>"
        if c == 0x5B:
            self.pos += 1
            return "["
        if c == 0x5D:
            self.pos += 1
            return "]"
        if c == 0x2F:  # '/'
            self.pos += 1
            start = self.pos
            while self.pos < n and d[self.pos] not in b"\x00\t\n\r\f ()<>[]{}/%":
                self.pos += 1
            return ("name", d[start:self.pos])
        if c == 0x28:  # '('
            depth = 1
            self.pos += 1
            out = bytearray()
            while self.pos < n and depth:
                ch = d[self.pos]
                if ch == 0x5C:  # backslash
                    nxt = d[self.pos + 1] if self.pos + 1 < n else b""
                    if nxt in b"nrtbf":
                        out += {ord('n'): b"\n", ord('r'): b"\r", ord('t'): b"\t",
                                ord('b'): b"\b", ord('f'): b"\f"}[nxt[0]]
                        self.pos += 2
                    elif nxt in b"01234567":
                        val = 0
                        for _ in range(3):
                            if self.pos + 1 < n and d[self.pos + 1] in b"01234567":
                                val = val * 8 + (d[self.pos + 1] - 48)
                                self.pos += 1
                        out += bytes([val])
                        self.pos += 1
                    elif nxt == 0x0D and self.pos + 2 < n and d[self.pos + 2] == 0x0A:
                        self.pos += 3
                    elif nxt in b"\r\n":
                        self.pos += 2
                    else:
                        out += bytes([nxt[0]]) if nxt else b""
                        self.pos += 2
                elif ch == 0x28:
                    depth += 1
                    out += b"("
                    self.pos += 1
                elif ch == 0x29:
                    depth -= 1
                    if depth:
                        out += b")"
                    self.pos += 1
                else:
                    out += bytes([ch])
                    self.pos += 1
            return ("str", bytes(out))
        if c in b"0123456789+-.":
            start = self.pos
            while self.pos < n and d[self.pos] in b"0123456789+-.":
                self.pos += 1
            num = d[start:self.pos]
            # check for indirect ref
            save = self.pos
            self.skip_ws()
            if self.pos < n and d[self.pos] in b"0123456789":
                start2 = self.pos
                while self.pos < n and d[self.pos] in b"0123456789":
                    self.pos += 1
                num2 = d[start2:self.pos]
                save2 = self.pos
                self.skip_ws()
                if self.pos < n and d[self.pos:self.pos + 1] == b"R":
                    self.pos += 1
                    return ("ref", (int(num), int(num2)))
                self.pos = save2
            self.pos = save
            if b"." in num:
                return ("num", float(num))
            return ("num", int(num))
        if d.startswith(b"true", self.pos):
            self.pos += 4
            return ("bool", True)
        if d.startswith(b"false", self.pos):
            self.pos += 5
            return ("bool", False)
        if d.startswith(b"null", self.pos):
            self.pos += 4
            return ("null", None)
        raise ValueError(f"unexpected token at {self.pos}: {d[self.pos:self.pos+20]!r}")

    def parse_value(self):
        t = self.next()
        if t is None:
            return None
        if isinstance(t, tuple):
            return t
        if t == "<<":
            d = {}
            while True:
                k = self.next()
                if k == ">>":
                    break
                if not isinstance(k, tuple) or k[0] != "name":
                    raise ValueError(f"expected name key, got {k!r}")
                v = self.parse_value()
                d[k[1]] = v
            return ("dict", d)
        if t == "[":
            arr = []
            while True:
                save = self.pos
                nxt = self.next()
                if nxt == "]":
                    break
                self.pos = save
                arr.append(self.parse_value())
            return ("array", arr)
        return t


def parse_at(tok):
    """Parse one PDF value at current token position."""
    return tok.parse_value()


# ---------- xref parsing ----------
def read_xref_section(data, offset):
    """Return (entries dict, trailer dict) for xref at offset."""
    tok = Tok(data)
    tok.pos = offset
    t = tok.next()
    if t == b"xref":
        entries = {}
        while True:
            save = tok.pos
            nxt = tok.next()
            if nxt is None:
                break
            if isinstance(nxt, tuple) and nxt[0] == "num":
                start = nxt[1]
                nxt2 = tok.next()
                if isinstance(nxt2, tuple) and nxt2[0] == "num":
                    count = nxt2[1]
                    for i in range(count):
                        line = tok.next()
                        if isinstance(line, tuple) and line[0] == "num":
                            off = line[1]
                        else:
                            raise ValueError(f"bad xref entry at {tok.pos}")
                        gen = tok.next()
                        kind = tok.next()
                        if isinstance(kind, tuple) and kind[0] == "name":
                            pass
                        entries[start + i] = off
                    continue
                else:
                    tok.pos = save
                    break
            else:
                tok.pos = save
                break
        # trailer
        nxt = tok.next()
        if nxt == "trailer":
            tv = tok.parse_value()
            trailer = tv[1] if isinstance(tv, tuple) and tv[0] == "dict" else {}
        else:
            trailer = {}
        return entries, trailer
    else:
        # xref stream: rewind and parse object
        tok.pos = offset
        numtok = tok.next()
        if isinstance(numtok, tuple) and numtok[0] == "num":
            gen = tok.next()
            kw = tok.next()
            if kw == "obj":
                val = tok.parse_value()
                if isinstance(val, tuple) and val[0] == "dict":
                    d = val[1]
                    if d.get(b"Type") == ("name", b"XRef"):
                        length = d.get(b"/Length")
                        # skip stream data
                        nxt = tok.next()
                        if nxt == "stream":
                            ln = length[1] if isinstance(length, tuple) and length[0] == "num" else None
                            tok.skip_ws()
                            start = tok.pos
                            end = start + ln if ln is not None else tok.data.find(b"endstream", start)
                            stream_data = tok.data[start:end]
                            tok.pos = end + len(b"endstream")
                            w = d.get(b"/W")
                            index = d.get(b"/Index")
                            filt = d.get(b"/Filter")
                            if isinstance(filt, tuple) and filt[0] == "name" and filt[1] == b"FlateDecode":
                                stream_data = zlib.decompress(stream_data)
                            ws = [x[1] for x in w[1]] if w and w[0] == "array" else None
                            idx = [x[1] for x in index[1]] if index and index[0] == "array" else [0, d.get(b"/Size")[1]]
                            entries = {}
                            pos = 0
                            for i in range(0, len(idx), 2):
                                first, count = idx[i], idx[i + 1]
                                for j in range(count):
                                    fields = []
                                    for wi in ws:
                                        fields.append(int.from_bytes(stream_data[pos:pos + wi], "big"))
                                        pos += wi
                                    if fields[0] == 1:
                                        entries[first + j] = fields[1]
                                    elif fields[0] == 2:
                                        entries[first + j] = ("objstm", fields[1], fields[2])
                            return entries, d
                        else:
                            return {}, d
    return {}, {}


def collect_objects(data):
    """Follow startxref/Prev chain; return {objnum: offset} and trailer info."""
    m = re.search(rb"startxref\s+(\d+)", data)
    if not m:
        return {}, {}
    offset = int(m.group(1))
    all_entries = {}
    trailer = {}
    seen = set()
    while offset and offset not in seen:
        seen.add(offset)
        try:
            entries, tr = read_xref_section(data, offset)
        except Exception as e:
            print(f"  xref parse error at {offset}: {e}")
            break
        for k, v in entries.items():
            all_entries[k] = v
        if tr.get(b"/Prev") is not None and isinstance(tr[b"/Prev"], tuple):
            offset = tr[b"/Prev"][1]
        elif tr.get(b"/Prev") is not None:
            offset = int(tr[b"/Prev"])
        else:
            offset = 0
        if not trailer and tr:
            trailer = tr
    return all_entries, trailer


entries, trailer = collect_objects(data)
print("objects found:", len(entries))
objstm = [k for k, v in entries.items() if isinstance(v, tuple) and v[0] == "objstm"]
print("object streams (ObjStm) present:", len(objstm))
maxobj = max(entries, default=0)
print("max object number:", maxobj)

root_ref = trailer.get(b"/Root")
print("trailer /Root:", root_ref)
if isinstance(root_ref, tuple) and root_ref[0] == "ref":
    root_num = root_ref[1]
    off = entries.get(root_num)
    print("catalog object number:", root_num, "offset:", off)
    if off is not None and not isinstance(off, tuple):
        tok = Tok(data)
        tok.pos = off
        hdr = tok.next()
        tok.next()  # gen
        kw = tok.next()
        val = tok.parse_value()
        if isinstance(val, tuple) and val[0] == "dict":
            pages_ref = val[1].get(b"/Pages")
            print("catalog /Pages:", pages_ref)
            if isinstance(pages_ref, tuple) and pages_ref[0] == "ref":
                pnum = pages_ref[1]
                poff = entries.get(pnum)
                print("pages root object:", pnum, "offset:", poff)
                if poff is not None and not isinstance(poff, tuple):
                    tok2 = Tok(data)
                    tok2.pos = poff
                    tok2.next(); tok2.next(); tok2.next()
                    pv = tok2.parse_value()
                    if isinstance(pv, tuple) and pv[0] == "dict":
                        pd = pv[1]
                        print("pages dict keys:", [k.decode(errors="replace") for k in pd])
                        print("pages /Count:", pd.get(b"/Count"))
                        kids = pd.get(b"/Kids")
                        if isinstance(kids, tuple) and kids[0] == "array":
                            print("pages /Kids count:", len(kids[1]))
                            for kid in kids[1][:5]:
                                print("   kid:", kid)
                else:
                    print("  (pages root is in an object stream)")
        else:
            print("  (could not parse catalog dict)")

